{"version":3,"file":"home.js","sources":["pages/home/home.vue","../../../../../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvaG9tZS9ob21lLnZ1ZQ"],"sourcesContent":["<template>\n  <view class=\"home-bg\">\n    <view class=\"home-header\">\n      <text class=\"title\">北京交通大学校医院</text>\n      <view class=\"header-icons\">\n        <view class=\"header-icon\">⚙️</view>\n      </view>\n    </view>\n    <view class=\"banner\">\n      <image src=\"/static/hospitalpicture.png\" mode=\"aspectFill\" style=\"width: 100%; height: 100%; border-radius: 12rpx;\" />\n    </view>\n    <view class=\"visit-card card\" @click=\"onVisitCardClick\">\n      <view class=\"visit-left\">\n        <view class=\"weather\">周晴晴  女  20岁</view>\n        <view class=\"ecard\">电子就诊卡</view>\n        <view class=\"visit-no\">门诊号：M01078965</view>\n      </view>\n      <view class=\"visit-right\">\n        <view class=\"qrcode\">📱</view>\n        <view class=\"enter\">出示就诊码</view>\n      </view>\n    </view>\n    <view class=\"bind-tip card\">\n      <text class=\"plus\">+</text>\n      <text>首次使用，请绑定就诊人</text>\n    </view>\n    <view class=\"night-banner\">\n      <text>“ 晚间门诊 ” 专栏</text>\n      <button class=\"night-btn\" size=\"mini\">点击进入</button>\n    </view>\n    <view class=\"quick card\">\n      <view class=\"quick-grid\">\n        <view class=\"quick-item\">\n          <view class=\"quick-icon\">📝</view>\n          <text>按疾病挂号</text>\n        </view>\n        <view class=\"quick-item\">\n          <view class=\"quick-icon\">🏥</view>\n          <text>按科室挂号</text>\n        </view>\n        <view class=\"quick-item\">\n          <view class=\"quick-icon\">📊</view>\n          <text>报告查询</text>\n        </view>\n        <view class=\"quick-item\">\n          <view class=\"quick-icon\">🌐</view>\n          <text>互联网诊疗</text>\n        </view>\n      </view>\n    </view>\n    <view class=\"home-tabs card\">\n      <view \n        v-for=\"(tab, idx) in tabs\" \n        :key=\"tab\" \n        class=\"tab\" \n        :class=\"{ active: idx === activeIndex }\"\n        @click=\"activeIndex = idx\"\n      >{{ tab }}</view>\n    </view>\n    <view class=\"home-section card\">\n      <view class=\"home-grid\">\n        <view \n          v-for=\"item in currentItems\" \n          :key=\"item.text\" \n          class=\"home-item\" \n          @click=\"onItemClick(item)\"\n        >\n          <view class=\"icon\">{{ item.icon }}</view>\n          <text>{{ item.text }}</text>\n        </view>\n      </view>\n    </view>\n    <!-- 未登录内联提示 -->\n    <LoginPrompt ref=\"loginPromptRef\" mode=\"inline\" message=\"登录后可出示电子就诊码\" login-text=\"去登录\" />\n    <view class=\"tabbar-placeholder\"></view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, computed } from 'vue'\nimport LoginPrompt from '@/components/LoginPrompt.vue'\nimport { AUTH_REQUIRED_FEATURES, createAuthHandler } from '@/utils/auth'\n\nconst tabs = ['门诊', '住院', '体检', '其他']\nconst activeIndex = ref(0)\nconst loginPromptRef = ref(null)\n\nconst itemsMap = {\n  门诊: [\n    { icon: '🌙', text: '晚间门诊' },\n    { icon: '📅', text: '周末门诊' },\n    { icon: '📋', text: '门诊签到' },\n    { icon: '🧠', text: '心理筛查门诊' },\n    { icon: '🗓️', text: '超声签到' },\n    { icon: '🧾', text: '看结果K号' },\n    { icon: '💴', text: '门诊缴费' },\n    { icon: '🔎', text: '检查预约' },\n    { icon: '🧾', text: '电子发票' },\n    { icon: '📂', text: '电子票夹' },\n    { icon: '🧭', text: '院内导航' },\n    { icon: '📘', text: '门诊服务指南' },\n    { icon: '📝', text: '预约记录' },\n    { icon: '💬', text: '护理咨询' },\n    { icon: '💳', text: '就诊卡余额退款' },\n    { icon: '📚', text: '病史采集' },\n    { icon: '🤖', text: '智能导诊' },\n  ],\n  住院: [\n    { icon: '💳', text: '住院预交' },\n    { icon: '🧾', text: '在院费用查询' },\n    { icon: '🪪', text: '电子陪护证' },\n    { icon: '📄', text: '病案复印' },\n    { icon: '🧾', text: '住院发票清单' },\n    { icon: '📘', text: '住院服务指南' },\n    { icon: '🍱', text: '住院订餐' },\n    { icon: '🧾', text: '订单清单' },\n    { icon: '🍼', text: '出生证预约' },\n    { icon: '🧠', text: '心理筛查住院' },\n    { icon: '📊', text: '满意度调查' },\n  ],\n  体检: [\n    { icon: '👤', text: '个检预约' },\n    { icon: '👥', text: '团检预约' },\n    { icon: '🗂️', text: '体检报告' },\n    { icon: '🧾', text: '体检订单' },\n    { icon: '🏥', text: '体检中心' },\n  ],\n  其他: [\n    { icon: '📚', text: '健康百科' },\n    { icon: '📣', text: '科普宣教' },\n    { icon: '🆘', text: '帮助与反馈' },\n    { icon: '💴', text: '价目公示' },\n    { icon: '➕', text: '移动随访' },\n    { icon: '🚑', text: '院前急救' },\n    { icon: '💉', text: '惠民复诊' },\n  ],\n}\n\nconst currentItems = computed(() => itemsMap[tabs[activeIndex.value]] || [])\n\nconst onItemClick = (item) => {\n  uni.showToast({ title: item.text, icon: 'none' })\n}\n\n// 使用统一的权限控制（需要就诊卡）\nconst onVisitCardClick = createAuthHandler(\n  AUTH_REQUIRED_FEATURES.HOME.VISIT_CARD,\n  '/subpkg/profile/personal/mycard',\n  { requireCard: true }\n)\n</script>\n\n<style scoped>\n.home-bg {\n  background: #f8faff;\n  min-height: 100vh;\n  padding-bottom: 120rpx;\n}\n.home-header {\n  background: #3a9cff;\n  height: 120rpx;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 32rpx;\n}\n.title {\n  color: #fff;\n  font-size: 36rpx;\n  font-weight: bold;\n}\n.header-icons {\n  display: flex;\n  align-items: center;\n}\n.header-icon {\n  width: 48rpx;\n  height: 48rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 24rpx;\n}\n.banner {\n  width: 100%;\n  height: 180rpx;\n  margin-bottom: 16rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 80rpx;\n  background: #f0f0f0;\n  border-radius: 12rpx;\n}\n.bind-tip {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: linear-gradient(90deg, #3a9cff 0%, #1de9b6 100%);\n  color: #fff;\n  font-size: 28rpx;\n  border-radius: 16rpx;\n  margin: 16rpx 24rpx 0 24rpx;\n  padding: 24rpx 0;\n  font-weight: bold;\n}\n.plus {\n  font-size: 36rpx;\n  margin-right: 16rpx;\n}\n.special-banner {\n  width: 92%;\n  margin: 24rpx 4% 0 4%;\n  border-radius: 16rpx;\n  height: 120rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 60rpx;\n  background: #f0f0f0;\n}\n.visit-card {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin: 16rpx 24rpx 0 24rpx;\n  padding: 16rpx 24rpx;\n}\n.visit-left .weather { font-size: 26rpx; color: #fff; }\n.visit-left .ecard { margin-top: 8rpx; background: #fff; color: #3a9cff; display: inline-block; padding: 6rpx 12rpx; border-radius: 8rpx; font-size: 24rpx; }\n.visit-left .visit-no { margin-top: 8rpx; color: #fff; font-size: 26rpx; }\n.visit-right { display:flex; flex-direction: column; align-items: center; color:#fff; }\n.visit-right .qrcode { font-size: 48rpx; }\n.visit-right .enter { font-size: 22rpx; margin-top: 6rpx; }\n\n.night-banner {\n  margin: 16rpx 24rpx 0 24rpx;\n  height: 120rpx;\n  border-radius: 16rpx;\n  background: linear-gradient(90deg, #6a00ff 0%, #8a2eff 100%);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 24rpx;\n  color: #fff;\n  font-weight: bold;\n}\n.night-btn { background: #fff; color: #6a00ff; border-radius: 999rpx; padding: 8rpx 16rpx; }\n\n.quick .quick-grid { display: flex; }\n.quick-item { width: 25%; display: flex; flex-direction: column; align-items: center; }\n.quick-icon { width: 56rpx; height: 56rpx; display: flex; align-items: center; justify-content: center; font-size: 32rpx; margin-bottom: 8rpx; }\n.card {\n  background: #fff;\n  border-radius: 16rpx;\n  margin: 24rpx 24rpx 0 24rpx;\n  padding: 24rpx 0;\n  box-shadow: 0 4rpx 16rpx rgba(58,156,255,0.08);\n}\n.home-section {\n  margin-top: 24rpx;\n}\n.home-row {\n  display: flex;\n  flex-direction: row;\n  justify-content: flex-start;\n  align-items: center;\n  margin: 0 0 16rpx 0;\n}\n.home-grid {\n  display: flex;\n  flex-wrap: wrap;\n}\n.home-item {\n  width: 25%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  margin: 16rpx 0;\n}\n.icon {\